PRE = ("Generate an image. The attached photo is the exact product reference sheet for the Indian oral-care brand HABBITS. "
       "Products: Te-Cha Charcoal Mint Toothpaste (matte black tube, vertical white 'Habbits' serif wordmark), Natural Whitening Powder (matte black jar, white tooth logo), "
       "Advance Whitening Serum (slim black pump bottle). Reproduce every product you show exactly as in the reference: same shape, matte black packaging, the 'Habbits' wordmark, the tooth logo, same label layout. "
       "Do not add text to labels that is not in the reference. Do not invent other products or brands. ")
SUF = (" [NO PLATFORM CHROME] Render only the standalone ad creative. No phone status bar, device frame, Sponsored label, captions, like counts or buttons unless explicitly described as part of the design."
       " [EDGE-SAFE] All text and products stay within the central 84% of the canvas, about 8% padding from every edge; nothing touches or runs off an edge."
       " [TEXT FIDELITY] Render exactly the words specified in double quotes, spelled exactly, no extra words, prices or claims anywhere. Inside chat bubbles or notes: plain words only, no emoji, and exactly the number of lines or messages specified.")
REAL = (" PHOTOREALISM: full-frame camera, 35-50mm lens, natural skin texture with pores, real fabric creases, true-to-life light, slight grain. Looks like a real unretouched photograph of real people, not CGI. "
        "Indian subject with natural Indian skin tone. Anatomy must be correct: exactly two arms and two hands, five fingers each. ")
TRIO = "the three products side by side, equal spacing, labels facing camera: the black Te-Cha toothpaste tube, the black Whitening Powder jar, the slim black Whitening Serum pump bottle"
PILL = "a small rounded pill badge in lime #C9F24B with black bold text \"BUY 2 GET 1 FREE\""

SYS = {
'M': " [DESIGN SYSTEM: MINIMAL SWISS] Premium, uncluttered. ONE focal point: the headline is the dominant element, at least 3x larger than any other text. At least 40% empty negative space. No props of any kind. Colour 60-30-10: warm off-white #F4F1EC background, black products, lime #C9F24B accent on the offer pill only. Everything on one centre axis. Soft even studio light, crisp product photography, heavy modern grotesque sans-serif.",
'T': " [DESIGN SYSTEM: BOLD TYPOGRAPHY] Type is the hero: the headline fills about 60% of the canvas, heavy condensed sans-serif, tight leading, set flush left. Products are small (under 20% of the height) in the lower right. Only two colours plus the offer pill. No props, no gradients, no decorations.",
'N': " [DESIGN SYSTEM: NATIVE LO-FI] Must look like something an ordinary person made on their phone, not an advertisement: plain default phone UI typography, no brand styling, no polish, casual real phone-camera photo quality. It should blend into a social feed.",
'F': " [DESIGN SYSTEM: FACE AND GAZE] A real person's face draws attention first; their eye-line points at the product and the offer, not at the camera, so the viewer's eye follows it. Product large and legible. Headline sits in clean empty space away from the face.",
'H': " [DESIGN SYSTEM: PRODUCT HERO CONTRAST] One product or group is visually isolated and different from everything else, so it pops out instantly. Single dramatic light source, deep clean shadows, museum-like emptiness. Minimal text.",
'P': " [DESIGN SYSTEM: PROOF AND DATA] Clean information design: the numbers are the hero. Strict grid, precise alignment, tabular figures, generous spacing, black on warm off-white #F4F1EC with lime #C9F24B used only on the final number or the offer.",
'A': " [DESIGN SYSTEM: RICH ART DIRECTION] Editorial magazine-quality lifestyle photograph, a fully styled real scene with warm natural light and depth. The richness is in the image, not in the text: still one clear message and one headline.",
'U': " [DESIGN SYSTEM: DELIBERATELY UGLY] Intentionally amateur and scrappy, like a rushed homemade post: flat phone flash, slightly crooked framing, marker handwriting or MS Paint style. It must look unpolished, but the headline and the offer must still be large and perfectly legible.",
}


def P_(body, s, real=False):
    return PRE + (REAL if real else "") + "1:1 static ad creative, 1080x1080. " + body + SYS[s] + SUF


P = {}
