P['C2_T_OneDay'] = P_("Background solid matte black #111111. Headline in huge heavy condensed off-white #F4F1EC sans-serif, flush left, filling the upper 60%: \"NO, IT WON'T\" / \"WORK IN\" / \"1 DAY.\" Under it one small off-white line: \"It takes 4 weeks. The 3rd one's free.\" Lower right, small: " + TRIO + ". Lower left: " + PILL + ". That is ALL the text.", 'T')
P['C2_P_OneDay'] = P_("Top 25%: headline in heavy black sans-serif, centred, two lines: \"NO, IT WON'T\" / \"WORK IN 1 DAY.\" Middle 35%: a clean horizontal 4-step progress chart: four equal columns labelled \"WEEK 1\", \"WEEK 2\", \"WEEK 3\", \"WEEK 4\", with a bar under them that fills progressively from light grey to solid black, ending at WEEK 4 with a lime #C9F24B marker and the label \"3X whiter in 30 days\". Bottom 30%: " + TRIO + ", small, standing alone on the plain background, and " + PILL + " centred below them. Show ONLY the three product containers: no grapefruit, no mint leaves, no charcoal pieces, no paste smears, no flowers, no plate, no serum box, no brush. That is ALL the text.", 'P')
