P['C3_F_GroupPhoto'] = P_("Evening in a warm Indian cafe. A 24-year-old Indian woman in a casual cotton kurta sits at a wooden table on the right half of the frame, looking down at her phone in one hand (screen not visible to us) with a small amused wince; her gaze and head angle point down-left towards the table where " + TRIO + " stand next to a half-finished glass of cutting chai. Top-left clean wall space: headline in heavy off-white sans-serif, two lines: \"ZOOMED INTO THE\" / \"GROUP PHOTO.\" and a smaller line below: \"Saw every chai I've ever had.\" Bottom-left above the products: " + PILL + ". That is ALL the text.", 'F', real=True)
P['C3_N_GroupPhoto'] = P_("A candid, slightly blurry phone photo of four Indian friends in their twenties laughing together at a house party, warm indoor light, flash, not posed, like a real group photo. Over it, casual white phone-story style text with a thin black outline, top area: \"zoomed into the group photo.\" and on the next line: \"saw every chai i've ever had.\" In the lower right corner, like a sticker, a small clean cut-out of " + TRIO + " with a white rounded label under them in bold black text: \"buy 2 get 1 free\", large and easy to read (label text about as big as the top caption). Drinks in hand are steel glasses of chai, no red plastic cups. That is ALL the text.", 'N', real=True)
P['C3_A_GroupPhoto'] = P_("Top-down editorial flat lay on a warm terracotta-and-cream table at golden hour: two clay kulhad cups of chai, a phone lying face up showing a softly blurred group photo of friends, a few marigold petals, and " + TRIO + " lying neatly in a row as the clear focus. Upper third kept calm and empty of objects for the headline in heavy cream #F4F1EC sans-serif, two lines: \"ZOOMED INTO THE\" / \"GROUP PHOTO.\" with a smaller line: \"Saw every chai I've ever had.\" Bottom centre: " + PILL + ". That is ALL the text.", 'A')
